D="/c/Users/coneil/AppData/Local/Temp/claude/87995a179e8ca25a/62d1c137-a316-4c55-b30a-3f6dac53053e/scratchpad/research/ct-physics"; cat > "$D/scripts/compute.js" <<'EOF'
// Recompute linear attenuation coefficients, transmission and HU from NIST XCOM-based tables
// Values of mu/rho (cm2/g) copied exactly from NIST XrayMassCoef ComTab pages; densities from tab2.
const fs = require('fs');
const base = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/ComTab/';
const M = [
  { material: 'Air (dry, near sea level)', key: 'air', rho: 1.205e-3, m60: 0.1875, m80: 0.1662, m500: 0.08712, m600: 0.08055, page: 'air.html' },
  { material: 'Inflated lung (lung-tissue mu/rho at density 0.26 g/cm3)', key: 'lung', rho: 0.26, m60: 0.2053, m80: 0.1826, m500: 0.09607, m600: 0.08882, page: 'lung.html' },
  { material: 'Adipose tissue (fat)', key: 'adipose', rho: 0.95, m60: 0.1974, m80: 0.1800, m500: 0.09696, m600: 0.08965, page: 'adipose.html' },
  { material: 'Water (liquid)', key: 'water', rho: 1.0, m60: 0.2059, m80: 0.1837, m500: 0.09687, m600: 0.08956, page: 'water.html' },
  { material: 'Soft tissue (ICRU-44)', key: 'soft', rho: 1.06, m60: 0.2048, m80: 0.1823, m500: 0.09598, m600: 0.08873, page: 'tissue.html' },
  { material: 'Skeletal muscle', key: 'muscle', rho: 1.05, m60: 0.2048, m80: 0.1823, m500: 0.09598, m600: 0.08874, page: 'muscle.html' },
  { material: 'Cortical bone (ICRU-44)', key: 'bone', rho: 1.92, m60: 0.3148, m80: 0.2229, m500: 0.09022, m600: 0.08332, page: 'bone.html' },
];
function loglog(E, E1, y1, E2, y2) {
  return Math.exp(Math.log(y1) + (Math.log(y2) - Math.log(y1)) * (Math.log(E) - Math.log(E1)) / (Math.log(E2) - Math.log(E1)));
}
const out = {};
for (const m of M) {
  m.mr70 = loglog(70, 60, m.m60, 80, m.m80);
  m.mr511 = loglog(511, 500, m.m500, 600, m.m600);
  m.mu70 = m.mr70 * m.rho;
  m.mu511 = m.mr511 * m.rho;
  m.mu60 = m.m60 * m.rho; m.mu80 = m.m80 * m.rho;
}
const w = M.find(x => x.key === 'water'), a = M.find(x => x.key === 'air');
for (const m of M) {
  m.hu70 = 1000 * (m.mu70 - w.mu70) / (w.mu70 - a.mu70);
  m.hu60 = 1000 * (m.mu60 - w.mu60) / (w.mu60 - a.mu60);
  m.hu80 = 1000 * (m.mu80 - w.mu80) / (w.mu80 - a.mu80);
  m.T = [1, 5, 10, 20].map(x => 100 * Math.exp(-m.mu70 * x));
  m.T511 = [1, 5, 10, 20].map(x => 100 * Math.exp(-m.mu511 * x));
  m.hvl70 = Math.log(2) / m.mu70; m.hvl511 = Math.log(2) / m.mu511;
}
for (const m of M) {
  console.log(m.key.padEnd(8), 'rho', m.rho, 'mr70', m.mr70.toFixed(5), 'mu70', m.mu70.toPrecision(4), 'mr511', m.mr511.toFixed(5), 'mu511', m.mu511.toPrecision(4),
    'HU60', m.hu60.toFixed(0), 'HU70', m.hu70.toFixed(0), 'HU80', m.hu80.toFixed(0));
  console.log('   T70 %', m.T.map(t => t.toPrecision(4)).join(', '), ' T511 %', m.T511.map(t => t.toPrecision(4)).join(', '), 'HVL70 cm', m.hvl70.toPrecision(3), 'HVL511 cm', m.hvl511.toPrecision(3));
}
// pair survival at 511 keV: both photons must escape -> exp(-mu*D) for total path D
for (const Dcm of [10, 20, 30, 40]) console.log('pair survival water total path', Dcm, 'cm:', (100 * Math.exp(-w.mu511 * Dcm)).toPrecision(3), '%  correction factor', Math.exp(w.mu511 * Dcm).toPrecision(3));
// bone/water ratios
const b = M.find(x => x.key === 'bone');
console.log('bone/water mu ratio 70keV', (b.mu70 / w.mu70).toFixed(2), '511keV', (b.mu511 / w.mu511).toFixed(2), 'mass ratio 70', (b.mr70 / w.mr70).toFixed(2), 'mass 511', (b.mr511 / w.mr511).toFixed(3));
// bilinear check: slope mu511 vs HU for water-bone using these numbers
console.log('bone HU70', b.hu70.toFixed(0), 'slope above 0:', ((b.mu511 - w.mu511) / b.hu70).toExponential(3), 'per cm per HU; below 0:', ((w.mu511 - a.mu511) / 1000).toExponential(3));
fs.writeFileSync(process.argv[2], JSON.stringify(M.map(m => ({ ...m, sourceUrl: base + m.page })), null, 1));
EOF
node "$D/scripts/compute.js" "$D/scripts/computed.json"

