// Builds draft.json for batch "ct-physics". All derived numbers are computed here.
// Usage: node build_draft.js <output path>
const fs = require('fs');
const NIST = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/ComTab/';
const TAB2 = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/tab2.html';
const TAB4 = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/tab4.html';
const XCOM_COMP = 'https://physics.nist.gov/cgi-bin/Xcom/xcom2?Method=Comp&Output2=Hand';
const XCOM_MIX = 'https://physics.nist.gov/cgi-bin/Xcom/xcom2?Method=Mix&Output2=Hand';
const IAEA = 'https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1564webNew-74666420.pdf';
const eutils = id => 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=pubmed&id=' + id + '&rettype=abstract&retmode=text';
const KINAHAN98 = eutils(9800714), KINAHAN03 = eutils(12931319), CARNEY06 = eutils(16696474), BURGER02 = eutils(12111133);
const TOWNSEND04 = 'https://jnm.snmjournals.org/content/45/1_suppl/4S.full.pdf';
const BAI03 = 'https://jnm.snmjournals.org/content/jnumed/44/11/1855.full.pdf';
const WILLEMINK = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6443602/';
const KOETZIER = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9968777/';
const CORMACK = 'https://www.nobelprize.org/uploads/2018/06/cormack-lecture.pdf';
const HOUNSFIELD = 'https://www.nobelprize.org/uploads/2018/06/hounsfield-lecture.pdf';
const NOBELPRESS = 'https://www.nobelprize.org/prizes/medicine/1979/press-release/';
const SURESHBABU = 'https://tech.snmjournals.org/content/33/3/156';
const BOELLAARD = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4315529/';
const VISION = 'https://www.siemens-healthineers.com/en-us/molecular-imaging/pet-ct/biograph-vision';
const FORCE = 'https://www.siemens-healthineers.com/en-us/computed-tomography/dual-source-ct/somatom-force';
const NAEOTOM = 'https://www.siemens-healthineers.com/en-us/computed-tomography/photon-counting-ct-scanner/naeotom-alpha';
const CANON = 'https://us.medical.canon/products/computed-tomography/aquilion-one-insight/';
const GEPR = 'https://www.gehealthcare.com/en-us/about/newsroom/press-releases/ge-healthcare-introduces-modular-scalable-ct-platform-to-minimize-technology-obsolescence';
const FDA_GE = 'https://www.accessdata.fda.gov/cdrh_docs/pdf21/K213715.pdf';
const LAMBA = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5015439/';
const PICKHARDT = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3736840/';
const AORTA1 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9816921/';
const AORTA2 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12426566/';
const EFFE1 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5966206/';
const EFFE2 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7851788/';
const HEADPH = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8693332/';
const HU1980 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6160654/';

// ---- data read from NIST (cm2/g) ----
// m60, m80, m500, m600: X-ray mass attenuation coefficient tables (tab4 pages), exactly as printed.
// x70, x511: NIST XCOM run directly at 0.07 and 0.511 MeV ("total attenuation with coherent scattering").
// coh/inc/pe: XCOM partial coefficients at 0.07 MeV; coh511/inc511/pe511 at 0.511 MeV.
const M = [
 { key:'air', material:'Air (dry, near sea level)', rho:1.205e-3, m60:0.1875, m80:0.1662, m500:0.08712, m600:0.08055, x70:0.1750, x511:0.08632, coh:0.01031, inc:0.1555, pe:0.009157, coh511:2.110e-4, inc511:0.08609, pe511:1.886e-5, page:'air.html', hu:[-1000,-1000] },
 { key:'lung', material:'Inflated lung (NIST lung-tissue mu/rho applied at an assumed density of 0.26 g/cm3)', rho:0.26, m60:0.2053, m80:0.1826, m500:0.09607, m600:0.08882, x70:0.1920, x511:0.09519, coh:0.01032, inc:0.1720, pe:0.009643, coh511:2.121e-4, inc511:0.09496, pe511:1.963e-5, page:'lung.html', hu:[-950,-600] },
 { key:'adipose', material:'Adipose tissue (fat)', rho:0.95, m60:0.1974, m80:0.1800, m500:0.09696, m600:0.08965, x70:0.1875, x511:0.09607, coh:0.007882, inc:0.1744, pe:0.005185, coh511:1.597e-4, inc511:0.09590, pe511:1.022e-5, page:'adipose.html', hu:[-130,-70] },
 { key:'water', material:'Water (liquid)', rho:1.0, m60:0.2059, m80:0.1837, m500:0.09687, m600:0.08956, x70:0.1929, x511:0.09598, coh:0.01048, inc:0.1734, pe:0.008969, coh511:2.151e-4, inc511:0.09575, pe511:1.778e-5, page:'water.html', hu:[0,0] },
 { key:'soft', material:'Soft tissue (ICRU-44)', rho:1.06, m60:0.2048, m80:0.1823, m500:0.09598, m600:0.08873, x70:0.1916, x511:0.09510, coh:0.01019, inc:0.1719, pe:0.009547, coh511:2.093e-4, inc511:0.09487, pe511:1.950e-5, page:'tissue.html', hu:[20,70] },
 { key:'muscle', material:'Skeletal muscle', rho:1.05, m60:0.2048, m80:0.1823, m500:0.09598, m600:0.08874, x70:0.1916, x511:0.09511, coh:0.01017, inc:0.1719, pe:0.009512, coh511:2.089e-4, inc511:0.09488, pe511:1.945e-5, page:'muscle.html', hu:[10,65] },
 { key:'bone', material:'Cortical bone (ICRU-44)', rho:1.92, m60:0.3148, m80:0.2229, m500:0.09022, m600:0.08332, x70:0.2570, x511:0.08938, coh:0.02157, inc:0.1582, pe:0.07729, coh511:4.704e-4, inc511:0.08873, pe511:1.862e-4, page:'bone.html', hu:[300,2500] },
];
const loglog = (E,E1,y1,E2,y2) => Math.exp(Math.log(y1) + (Math.log(y2)-Math.log(y1))*(Math.log(E)-Math.log(E1))/(Math.log(E2)-Math.log(E1)));
const sig = (x,n=4) => Number(x.toPrecision(n));
const T = (mu,x) => 100*Math.exp(-mu*x);
for (const m of M) {
  m.mr70 = loglog(70,60,m.m60,80,m.m80); m.mr511 = loglog(511,500,m.m500,600,m.m600);
  m.mu70 = m.mr70*m.rho; m.mu511 = m.mr511*m.rho;
  m.mu70x = m.x70*m.rho; m.mu511x = m.x511*m.rho;
  m.mu60 = m.m60*m.rho; m.mu80 = m.m80*m.rho;
}
const by = k => M.find(m => m.key===k);
const w = by('water'), a = by('air'), b = by('bone'), l = by('lung'), f = by('adipose'), s = by('soft'), mu_ = by('muscle');
const HU2 = (mu,muw,mua) => 1000*(mu-muw)/(muw-mua);   // two-point form
const HU1 = (mu,muw) => 1000*(mu-muw)/muw;             // IAEA form
for (const m of M) {
  m.hu60 = HU2(m.mu60,w.mu60,a.mu60); m.hu70 = HU2(m.mu70,w.mu70,a.mu70); m.hu80 = HU2(m.mu80,w.mu80,a.mu80);
}
const airHU_iaeaForm = HU1(a.mu70,w.mu70);

// ---- tables ----
const attenuation = M.map(m => ({
  material: m.material,
  density_g_cm3: m.rho,
  massAtt_60keV: m.m60, massAtt_80keV: m.m80, massAtt_500keV: m.m500, massAtt_600keV: m.m600,
  massAtt_70keV_loglog: sig(m.mr70), massAtt_511keV_loglog: sig(m.mr511),
  mu_70keV_per_cm: sig(m.mu70), mu_511keV_per_cm: sig(m.mu511),
  xcom_massAtt_70keV: m.x70, xcom_massAtt_511keV: m.x511,
  xcom_mu_70keV_per_cm: sig(m.mu70x), xcom_mu_511keV_per_cm: sig(m.mu511x),
  halfValueLayer_70keV_cm: sig(Math.log(2)/m.mu70,3), halfValueLayer_511keV_cm: sig(Math.log(2)/m.mu511,3),
  computedHU_monoenergetic: { at60keV: Math.round(m.hu60), at70keV: Math.round(m.hu70), at80keV: Math.round(m.hu80) },
  typicalHU: m.hu,
  sourceUrl: NIST + m.page,
}));
const transmission = M.map(m => ({
  material: m.material,
  mu_70keV_per_cm: sig(m.mu70),
  pctThrough_1cm: sig(T(m.mu70,1),4), pctThrough_5cm: sig(T(m.mu70,5),4), pctThrough_10cm: sig(T(m.mu70,10),3), pctThrough_20cm: sig(T(m.mu70,20),3),
  xcomCheck_pctThrough: { cm1: sig(T(m.mu70x,1),4), cm5: sig(T(m.mu70x,5),4), cm10: sig(T(m.mu70x,10),3), cm20: sig(T(m.mu70x,20),3) },
  at511keV_pctThrough: { cm1: sig(T(m.mu511,1),4), cm5: sig(T(m.mu511,5),4), cm10: sig(T(m.mu511,10),3), cm20: sig(T(m.mu511,20),3) },
  calculation: 'percent = 100 x exp(-mu x thickness); 1 cm: 100 x exp(-' + sig(m.mu70) + ' x 1) = ' + sig(T(m.mu70,1),4) + '; 5 cm: 100 x exp(-' + sig(m.mu70) + ' x 5) = ' + sig(T(m.mu70,5),4) + '; 10 cm: ' + sig(T(m.mu70,10),3) + '; 20 cm: ' + sig(T(m.mu70,20),3),
}));
const interactions = ['water','soft','adipose','bone'].map(k => { const m = by(k); const t = m.coh+m.inc+m.pe, t5 = m.coh511+m.inc511+m.pe511; return {
  material: m.material,
  at70keV_pct: { photoelectricAbsorption: sig(100*m.pe/t,3), comptonScatter: sig(100*m.inc/t,3), rayleighScatter: sig(100*m.coh/t,3) },
  at511keV_pct: { photoelectricAbsorption: sig(100*m.pe511/t5,2), comptonScatter: sig(100*m.inc511/t5,4), rayleighScatter: sig(100*m.coh511/t5,2) },
  xcom_cm2_per_g_at70keV: { coherent: m.coh, incoherent: m.inc, photoelectric: m.pe, total: m.x70 },
  xcom_cm2_per_g_at511keV: { coherent: m.coh511, incoherent: m.inc511, photoelectric: m.pe511, total: m.x511 },
}; });
const pairSurvival = [10,20,30,40].map(Dc => ({ totalPathInWater_cm: Dc, pctOfPhotonPairsDetectable: sig(T(w.mu511,Dc),3), correctionFactor: sig(Math.exp(w.mu511*Dc),3) }));
const compton = E => ({ incident_keV: E, after90deg_keV: sig(E/(1+E/511),3), after180deg_keV: sig(E/(1+2*E/511),3) });
const hounsfield = [
  { tissue:'Air', typicalHU:[-1000,-1000], basis:'Fixed point of the scale.', sources:[IAEA, HOUNSFIELD] },
  { tissue:'Lung (inflated)', typicalHU:[-950,-600], basis:'IAEA handbook Table 11.1: -750 (-950 to -600). Computed here for density 0.26 g/cm3: ' + Math.round(l.hu70) + ' HU.', sources:[IAEA] },
  { tissue:'Fat', typicalHU:[-130,-70], basis:'IAEA Table 11.1: -90 (-100 to -80). Measured subcutaneous fat in 48 adults on two scanners: means -103 to -113, individual values -130 to -79 (Lamba 2014). Hounsfield 1980 as quoted in a 2018 paper: -90 to -70.', sources:[IAEA, LAMBA, HU1980] },
  { tissue:'Water', typicalHU:[0,0], basis:'Fixed point of the scale.', sources:[IAEA, HOUNSFIELD] },
  { tissue:'Blood (unclotted, no contrast agent)', typicalHU:[30,60], basis:'IAEA Table 11.1: +55 (+50 to +60). Measured in the aorta on unenhanced CT: mean +37.7 (range +20 to +51) in 423 patients including anemic ones; about +45 in non-anemic patients. Lower with anemia.', sources:[IAEA, AORTA1, AORTA2] },
  { tissue:'Muscle', typicalHU:[10,65], basis:'IAEA Table 11.1: +25 (+10 to +40). Measured psoas muscle: means +44 to +49, individual values +22 to +67 (Lamba 2014). Computed here for ICRU-44 skeletal muscle: +' + Math.round(mu_.hu70) + '.', sources:[IAEA, LAMBA] },
  { tissue:'Liver', typicalHU:[45,70], basis:'IAEA Table 11.1: +60 (+50 to +70). Measured right lobe: means +47.5 and +50.4 on two scanners in a patient group that was not screened for fatty liver (individual values +10 to +77) (Lamba 2014). Fat in the liver lowers the value.', sources:[IAEA, LAMBA] },
  { tissue:'Spongy (cancellous, trabecular) bone', typicalHU:[50,300], basis:'Vertebral trabecular bone at L1 in 1867 adults: 160 HU or less was 90% sensitive for osteoporosis, and above 200 HU osteoporosis was very unlikely (Pickhardt 2013). Varies strongly with age and site. The [50, 300] range is my summary of that study, not a published reference range.', sources:[PICKHARDT] },
  { tissue:'Compact (cortical) bone', typicalHU:[300,2500], basis:'IAEA Table 11.1: +1000 (+300 to +2500). Skull about +1500 at 120 kV. Computed here for ICRU-44 cortical bone: +' + Math.round(b.hu80) + ' at 80 keV, +' + Math.round(b.hu70) + ' at 70 keV, +' + Math.round(b.hu60) + ' at 60 keV.', sources:[IAEA, HEADPH] },
];

// ---- numbers used in statements ----
const tot = m => m.coh+m.inc+m.pe;
const n = {
  wMu70: sig(w.mu70,3), wMu70x: sig(w.mu70x,3), wMu511: sig(w.mu511,3),
  bMu70: sig(b.mu70,3), bMu70x: sig(b.mu70x,3), bMu511: sig(b.mu511,3),
  ratioBW70: sig(b.mu70/w.mu70,3), ratioBW70x: sig(b.mu70x/w.mu70x,3), ratioBW511: sig(b.mu511/w.mu511,3),
  scaleWater: sig(w.mu511x/w.mu70x,3), scaleBone: sig(b.mu511x/b.mu70x,3),
  peW: sig(100*w.pe/tot(w),2), peB: sig(100*b.pe/tot(b),2),
  incW: sig(100*w.inc/tot(w),2), cohW: sig(100*w.coh/tot(w),2), incB: sig(100*b.inc/tot(b),2), cohB: sig(100*b.coh/tot(b),2),
  pePerGramRatio: sig(b.pe/w.pe,2), pePerCmRatio: sig(b.pe*b.rho/(w.pe*w.rho),3),
  hvlW70: sig(Math.log(2)/w.mu70,2), hvlW511: sig(Math.log(2)/w.mu511,2),
  airHU_iaeaForm: sig(airHU_iaeaForm,5),
  airOverWater70: sig(w.mu70/a.mu70,3),
  wholeBody_s: sig(1000/(64*0.6*1.0/0.5),3), wholeBody_speed_mm_s: sig(64*0.6*1.0/0.5,3),
  rps023: sig(1/0.23,3),
  carneyLung: sig(9.6e-5*(l.hu70+1000),3),
  musclePctAbove: sig(100*(mu_.mu70/w.mu70-1),2), softPctAbove: sig(100*(s.mu70/w.mu70-1),2), fatPctBelow: sig(100*(1-f.mu70/w.mu70),2),
  pair30: sig(T(w.mu511,30),2), pair30factor: sig(Math.exp(w.mu511*30),3),
};
const tr = k => transmission.find(t => t.material===by(k).material);
const lost1cm = m => Math.round(100*(1-Math.exp(-m.mu70)));
const four = t => [t.pctThrough_1cm,t.pctThrough_5cm,t.pctThrough_10cm,t.pctThrough_20cm];

const claims = [];
const C = (id, topic, statement, value, unit, range, sources, notes) => claims.push({ id, topic, statement, value: String(value), unit, range, status: 'unverified', sources, notes });

// ---- 1 ----
C('ct-tube-voltage', 'Claim 1: CT X-ray tube voltage',
 'A CT scanner runs its X-ray tube at a peak voltage between about 70 and 150 kilovolts, and 120 kilovolts is the usual setting for adult body scans.',
 '120', 'kV (peak tube voltage, also written kVp)',
 '70 to 150 kV depending on scanner model; many scanners offer 80, 100, 120 and 140 kV. The IAEA handbook gives 120 to 140 kV as usual, with 80 to 100 kV for contrast studies and children.',
 [IAEA, FORCE, VISION, NAEOTOM],
 'Draft confirmed. Read: IAEA Diagnostic Radiology Physics handbook (2014), section 11.6 ("a relatively high tube voltage (120-140 kV) is used ... a relatively low tube voltage, in the range 80-100 kV" for contrast and pediatric scans); the same handbook names 120 kV (beam quality RQT 9) as the standard calibration quality for CT. Siemens SOMATOM Force specification: "70 - 150 kV, in steps of 10 kV". Siemens Biograph Vision PET/CT: tube voltages 70, 80, 100, 120, 140 kV, so the CT inside a PET/CT may top out at 140 kV. Not every scanner offers 70 or 150 kV. "kVp" and "kV" are used interchangeably in the sources. "Usual setting for adult body scans" rests on the IAEA text and on 120 kV being the reference quality; low-dose CT done only for PET attenuation correction is sometimes run at 100 kV or lower.');
C('ct-beam-energy-spectrum', 'Claim 1: X-ray beam energy spectrum and effective energy',
 'The beam is a mix of photon energies up to the tube voltage (up to 120 keV at 120 kV), and on average it behaves like a single-energy beam of roughly 55 to 70 keV.',
 '55 to 70', 'keV (effective energy at 120 kV)',
 'Measured effective energy at 120 kV, in air at the scanner center: 54.4 and 62.4 keV on two scanners (one study), 54.9 to 58.0 keV on two other scanners (another study). PET/CT papers use about 70 keV for the beam inside the patient.',
 [EFFE1, EFFE2, KINAHAN98, KINAHAN03, TOWNSEND04],
 'CORRECTED from the draft "about 60 to 70 keV": measured effective energies at 120 kVp are often below 60 keV (54.4 keV and 62.4 keV in PMC5966206; 54.87 to 57.97 keV, mean 56.47, in PMC7851788). The PET/CT literature (Kinahan 1998 abstract: "effective CT photon energy of 70 keV"; Kinahan 2003: "approximately 70 keV"; Townsend 2004: "mean photon energy of 70 keV") uses 70 keV; the average energy rises as the body filters out low-energy photons (beam hardening). "Effective energy" (the single energy with the same half-value layer) and "mean energy" (the average of the spectrum) are different quantities and the sources use them loosely. Kinahan 1998 describes the CT photons as spanning 40 keV through 140 keV. The site tables use 70 keV to match the PET/CT convention; say "about 70 keV" rather than implying it is exact.');
// ---- 2 ----
C('beer-lambert-law', 'Claim 2: Beer-Lambert law',
 'The number of photons that get straight through a material falls off exponentially with thickness: I = I0 x exp(-mu x d), where I0 is the number going in, d is the thickness and mu is the linear attenuation coefficient of the material.',
 'I = I0 * exp(-mu * x)', '',
 'Exact only for a narrow beam of a single energy passing through one uniform material; for a path through several tissues the exponent is the sum (integral) of mu along the path.',
 [IAEA],
 'Draft confirmed. IAEA handbook Eq. 11.1 ("Beer\'s law": I(x) = I0 e^(-mu x)) and Eq. 11.2 for a path through varying tissue. The handbook notes that the law describes only the primary (unscattered) beam and that a real CT beam has many energies, which is the cause of the beam-hardening artifact. The names Beer\'s law, Beer-Lambert law and exponential attenuation law are all in use. The statement writes the thickness as d only to avoid "x x" in plain text; the usual symbol is x.');
// ---- 3 ----
C('water-attenuation-70-and-511-kev', 'Claim 3: attenuation table; water at 70 keV and 511 keV',
 'One centimeter of water removes about ' + lost1cm(w) + ' percent of 70 keV X-ray photons from the beam (mu about ' + sig(w.mu70,2) + ' per cm) but only about ' + Math.round(100*(1-Math.exp(-w.mu511))) + ' percent of the 511 keV photons used in PET (mu about 0.096 per cm).',
 'mu(water) = ' + sig(w.mu70) + ' per cm at 70 keV by log-log interpolation (' + sig(w.mu70x) + ' from NIST XCOM run at exactly 70 keV); ' + sig(w.mu511) + ' per cm at 511 keV', 'per cm',
 'Half-value thickness of water: about ' + n.hvlW70 + ' cm at 70 keV and about ' + n.hvlW511 + ' cm at 511 keV. PET papers quote 0.096 per cm (narrow beam) and about 0.093 per cm as measured on scanners that accept some scattered photons.',
 [NIST+'water.html', TAB4, XCOM_COMP, BURGER02, CARNEY06, BAI03],
 'Draft value 0.096 per cm CONFIRMED. NIST table values for water: 0.2059 (60 keV), 0.1837 (80 keV), 0.09687 (500 keV), 0.08956 (600 keV) cm2/g. Log-log interpolation gives ' + sig(w.mr70) + ' cm2/g at 70 keV and ' + sig(w.mr511) + ' cm2/g at 511 keV; NIST XCOM run at exactly those energies gives 0.1929 and 0.09598 cm2/g. Independent PET sources: Burger et al. 2002 (Eur J Nucl Med Mol Imaging 29:922-7, PMID 12111133) abstract: "the narrow-beam attenuation coefficient of water at 511 keV (0.096 cm-1)", and they measured 0.093 cm-1 from germanium-68 transmission scans; Carney et al. 2006 (Med Phys 33:976-83, PMID 16696474) use 9.6e-5 x (HU+1000), i.e. 0.096 per cm at 0 HU; Bai et al. 2003 (J Nucl Med 44:1855-61) use 0.096 cm-1 for soft tissue. PubMed abstracts were read through the NCBI E-utilities URLs listed, because pubmed.ncbi.nlm.nih.gov returned a bot check to curl. "Removes from the beam" means absorbed or scattered.');
C('attenuation-table-materials', 'Claim 3: attenuation table for seven materials',
 'At CT energies, one centimeter of dense bone removes about ' + lost1cm(b) + ' percent of the X-ray photons from the beam, water or muscle about ' + lost1cm(w) + ' percent, fat about ' + lost1cm(f) + ' percent, air-filled lung about ' + lost1cm(l) + ' percent, and air almost none.',
 'mu at 70 keV (per cm): ' + M.map(m => m.key + ' ' + sig(m.mu70)).join('; ') + '. mu at 511 keV (per cm): ' + M.map(m => m.key + ' ' + sig(m.mu511)).join('; '), 'per cm',
 'See tables.attenuation. Body tissues vary from person to person; lung varies most with breathing, and bone ranges from spongy to compact.',
 [TAB4, TAB2, ...M.map(m => NIST+m.page), XCOM_MIX],
 'Mass attenuation coefficients at 60, 80, 500 and 600 keV were read from the NIST pages and densities from NIST Table 2 (air 1.205E-03, adipose 0.950, water 1.000, soft tissue ICRU-44 1.060, skeletal muscle 1.050, cortical bone 1.920, lung tissue 1.050 g/cm3). mu at 70 and 511 keV by log-log interpolation as the task specified. CHECK: NIST XCOM run directly at 70 keV with the same compositions gives slightly lower values, because the curve between 60 and 80 keV is not a straight line on log-log axes: water 0.1929 vs 0.1937 cm2/g (0.4% lower), soft tissue 0.1916 vs 0.1924, fat 0.1875 vs 0.1879, cortical bone 0.2570 vs 0.2616 (1.8% lower). The XCOM values are in the table as xcom_* columns and are the better numbers if the site shows more than two significant figures; at 511 keV the two methods agree to 4 figures. DOUBT: the inflated-lung row uses the NIST lung-tissue mu/rho (tabulated for solid lung tissue, 1.05 g/cm3) at an assumed density of 0.26 g/cm3, as the task instructed. 0.26 g/cm3 is the inflated-lung value usually attributed to ICRU Report 44, but I could not open a primary source that states it; the site should say "inflated lung, assumed density 0.26 g/cm3". The computed HU for that row (' + Math.round(l.hu70) + ') sits inside the IAEA lung range (-950 to -600). typicalHU ranges come from the claim 5 sources, not from NIST. computedHU_monoenergetic shows what a single-energy beam would give; real scanners differ (for example the computed fat value at 70 keV, ' + Math.round(f.hu70) + ' HU, is less negative than the -100 to -115 HU usually measured).');
C('bone-vs-water-attenuation-ratio', 'Claim 3: attenuation table; bone compared with water at the two energies',
 'Dense bone attenuates 70 keV X-rays about 2.6 times as strongly as water, but 511 keV PET photons only about 1.8 times as strongly.',
 'mu(bone)/mu(water) = ' + n.ratioBW70 + ' at 70 keV (' + n.ratioBW70x + ' with XCOM values); ' + n.ratioBW511 + ' at 511 keV', 'ratio',
 'For ICRU-44 cortical bone at 1.92 g/cm3; less for spongy bone.',
 [NIST+'bone.html', NIST+'water.html', XCOM_MIX, TOWNSEND04],
 'Computed: bone ' + sig(b.mu70) + ' per cm and water ' + sig(w.mu70) + ' per cm at 70 keV; bone ' + sig(b.mu511) + ' and water ' + sig(w.mu511) + ' at 511 keV. This energy dependence is the reason one scale factor cannot convert a CT image to 511 keV: the ratio mu(511)/mu(70) is ' + n.scaleWater + ' for water and ' + n.scaleBone + ' for cortical bone (XCOM values). Townsend et al. 2004 state the same point in words: "Scale factors for bone are smaller than those for soft tissue".');
// ---- 4 ----
C('transmission-through-water-70-kev', 'Claim 4: percentage of 70 keV photons passing straight through',
 'Of 100 X-ray photons at 70 keV aimed into water, about ' + Math.round(tr('water').pctThrough_1cm) + ' pass straight through 1 cm, ' + Math.round(tr('water').pctThrough_5cm) + ' through 5 cm, ' + Math.round(tr('water').pctThrough_10cm) + ' through 10 cm and only ' + Math.round(tr('water').pctThrough_20cm) + ' through 20 cm.',
 [1,5,10,20].map((x,i) => x + ' cm: ' + four(tr('water'))[i] + '%').join('; '), 'percent',
 'Muscle and other soft tissue are within about 2 percentage points of water. See tables.transmission for all seven materials.',
 [NIST+'water.html', IAEA],
 'Calculation: percent = 100 x exp(-mu x thickness) with mu = ' + sig(w.mu70) + ' per cm. 1 cm: 100 x exp(-' + sig(w.mu70) + ') = ' + tr('water').pctThrough_1cm + '. 5 cm: ' + tr('water').pctThrough_5cm + '. 10 cm: ' + tr('water').pctThrough_10cm + '. 20 cm: ' + tr('water').pctThrough_20cm + '. With the XCOM value (0.1929 per cm) the results are ' + Object.values(tr('water').xcomCheck_pctThrough).join(' / ') + ' percent, the same whole numbers. "Straight through" means not absorbed and not scattered, for an ideal narrow single-energy beam; a real CT beam has a spread of energies and its average energy rises with depth, so real transmission through thick bodies is somewhat higher than these numbers. The script is scripts/build_draft.js in the batch scratch folder.');
C('transmission-through-bone-and-lung-70-kev', 'Claim 4: percentage of 70 keV photons passing straight through',
 'About ' + Math.round(tr('bone').pctThrough_1cm) + ' percent of 70 keV photons pass straight through 1 cm of dense bone and about ' + Math.round(tr('bone').pctThrough_5cm) + ' percent through 5 cm, while about ' + Math.round(tr('lung').pctThrough_10cm) + ' percent pass through 10 cm of air-filled lung.',
 'bone: ' + four(tr('bone')).join(' / ') + ' %; inflated lung: ' + four(tr('lung')).join(' / ') + ' %; fat: ' + four(tr('adipose')).join(' / ') + ' %; muscle: ' + four(tr('muscle')).join(' / ') + ' %; soft tissue: ' + four(tr('soft')).join(' / ') + ' %; air: ' + four(tr('air')).join(' / ') + ' % (for 1 / 5 / 10 / 20 cm)', 'percent',
 'Bone values are for compact (cortical) bone; no part of the body has 10 or 20 cm of solid cortical bone, so those two entries are illustrative only. Lung depends on how full of air it is.',
 [NIST+'bone.html', NIST+'lung.html', NIST+'adipose.html', NIST+'muscle.html', NIST+'tissue.html', NIST+'air.html'],
 'Calculation as for water, with mu from tables.attenuation (bone ' + sig(b.mu70) + ', lung ' + sig(l.mu70) + ', fat ' + sig(f.mu70) + ', muscle ' + sig(mu_.mu70) + ', soft tissue ' + sig(s.mu70) + ', air ' + sig(a.mu70) + ' per cm). CAUTION on thick bone: small differences in mu are magnified by the exponential. With the XCOM mu for bone (' + sig(b.mu70x) + ' per cm) the results are ' + Object.values(tr('bone').xcomCheck_pctThrough).join(' / ') + ' percent, so for 10 cm say "less than 1 percent" and for 20 cm say "less than 0.01 percent" rather than quoting digits.');
// ---- 5 ----
C('hounsfield-unit-definition', 'Claim 5: Hounsfield unit definition',
 'CT images are stored in Hounsfield units, which compare each tissue with water: HU = 1000 x (mu - mu_water) / mu_water, so 1 HU is a 0.1 percent difference from water.',
 'HU = 1000 * (mu - mu_water) / mu_water', 'HU',
 'Some texts write the denominator as (mu_water - mu_air), which fixes air at exactly -1000; because air attenuates about ' + Math.round(n.airOverWater70/10)*10 + ' times less than water, the two forms differ by about 1 HU at the air end and not at all at water.',
 [IAEA, HOUNSFIELD],
 'The draft formula, with (mu_water - mu_air) in the denominator, is an accepted variant, but the form with mu_water alone is the one given by the IAEA handbook (Eq. 11.4), which then states HU(air) = -1000 by taking mu_air = 0. With the NIST values at 70 keV the IAEA form gives air = ' + n.airHU_iaeaForm + ' HU, so "air is -1000" is a rounded convention under that form and exact under the two-point form; mu_water/mu_air at 70 keV = ' + n.airOverWater70 + '. The scale is named for Godfrey Hounsfield; in his 1979 Nobel lecture he describes the scale running "from air (-1000) at the bottom of the scale, to bone at the top", with water "chosen to be zero".');
C('hounsfield-air-and-water', 'Claim 5: Hounsfield units, fixed points',
 'On the Hounsfield scale water is 0 and air is -1000.',
 'water 0; air -1000', 'HU',
 'Fixed by definition and by scanner calibration; all other tissues shift a little with tube voltage, scanner model and reconstruction settings.',
 [IAEA, HOUNSFIELD],
 'Draft confirmed. IAEA handbook section 11.2.2 and Table 11.1; Hounsfield Nobel lecture ("air (-1000) ... water, which has been chosen to be zero"). The IAEA handbook notes that a 12-bit CT image covers -1024 to +3071 HU.');
C('hounsfield-lung', 'Claim 5: Hounsfield units, lung',
 'Air-filled lung measures about -950 to -600 HU, because it is mostly air.',
 '-750', 'HU', '-950 to -600 (IAEA); more negative at full breath-in, less negative at breath-out or where the lung is diseased or collapsed',
 [IAEA, NIST+'lung.html'],
 'Draft range (-900 to -500) replaced with the IAEA handbook Table 11.1 entry: Lung -750 (-950 to -600). The computed value for lung tissue at 0.26 g/cm3 and 70 keV is ' + Math.round(l.hu70) + ' HU, consistent with the table. The draft upper end of -500 is plausible for lung at breath-out but I did not find it in a source I could read.');
C('hounsfield-fat', 'Claim 5: Hounsfield units, fat',
 'Fat measures about -100 HU, slightly below water, typically between -130 and -70 HU.',
 '-100', 'HU', '-130 to -70. IAEA: -90 (-100 to -80). Measured in 48 adults on two scanners: mean -103 to -113, individual values -130 to -79.',
 [IAEA, LAMBA, HU1980],
 'Draft range (-120 to -60) adjusted: no source read supports values as high as -60 for pure fat. IAEA Table 11.1: Fat -90 (-100 to -80). Lamba et al. 2014 (AJR 203:1013-20), Table 2: subcutaneous fat means -102.9 to -113.4 HU, minimum -129.9, maximum -78.9. A 2018 paper quoting Hounsfield (1980) gives adipose -90 to -70. The same person measured on two scanners differed by about 10 HU in fat.');
C('hounsfield-blood', 'Claim 5: Hounsfield units, blood',
 'Blood without contrast agent measures roughly +30 to +60 HU, a little above water.',
 '+40 to +55', 'HU', '+30 to +60; lower in anemia (measured down to +20), higher when clotted',
 [IAEA, AORTA1, AORTA2],
 'Draft range (+30 to +45) WIDENED because sources disagree. IAEA Table 11.1: Blood +55 (+50 to +60). Measured in the aorta on unenhanced CT: mean +37.7 HU, range +20 to +51, in 423 patients of whom about a third were anemic (PMC9816921); about +45 HU in non-anemic and +33 to +36 HU in anemic patients (PMC12426566). The two clinical studies are single-center studies in a general medical journal; treat the numbers as typical, not exact. "Higher when clotted" is standard radiology teaching that I did not confirm in a source read for this batch; drop it if unsure.');
C('hounsfield-muscle', 'Claim 5: Hounsfield units, muscle',
 'Muscle measures roughly +10 to +65 HU, most often about +40 to +50 HU.',
 '+45', 'HU', '+10 to +65. IAEA: +25 (+10 to +40). Measured psoas muscle in 47 adults on two scanners: mean +44 to +49, individual values +22 to +67.',
 [IAEA, LAMBA, NIST+'muscle.html'],
 'Draft range (+35 to +55) widened because sources disagree. IAEA Table 11.1: Muscle +25 (+10 to +40). Lamba et al. 2014 Table 2: right and left psoas means 44.4, 44.0, 47.7, 49.4 HU; minimum 21.9, maximum 66.6. Computed for ICRU-44 skeletal muscle at 70 keV: +' + Math.round(mu_.hu70) + ' HU. Fat within a muscle lowers its value.');
C('hounsfield-liver', 'Claim 5: Hounsfield units, liver',
 'A healthy liver measures about +45 to +70 HU without contrast agent, and fat in the liver lowers the number.',
 '+55', 'HU', '+45 to +70. IAEA: +60 (+50 to +70). Measured in 45 adult patients on two scanners: mean +47.5 and +50.4.',
 [IAEA, LAMBA],
 'Draft range (+40 to +60) shifted slightly upward to match the sources read. IAEA Table 11.1: Liver +60 (+50 to +70). Lamba et al. 2014 Table 2: right lobe mean 47.5 HU (Siemens) and 50.4 HU (GE), individual values 9.6 to 77.2 HU in hospital patients not screened for fatty liver, which pulls the mean down. The lower end of +45 is my judgment between the two sources.');
C('hounsfield-spongy-bone', 'Claim 5: Hounsfield units, spongy (cancellous) bone',
 'Spongy bone, such as the inside of a vertebra, varies widely with age and bone health, from under +100 HU to +300 HU or more.',
 '+100 to +300', 'HU', 'In a study of 1867 adults, a first-lumbar-vertebra reading of 160 HU or less suggested osteoporosis and readings above 200 HU made it very unlikely; individual readings as low as 20 HU were shown.',
 [PICKHARDT, IAEA],
 'CORRECTED: the draft range "+300 to +400" is widely repeated on the web but I found no primary source for it, and measured vertebral spongy bone is usually lower. Pickhardt et al. 2013 (Ann Intern Med; PMC3736840): L1 trabecular attenuation of 160 HU or less was 90% sensitive, and 110 HU more than 90% specific, for osteoporosis; negative predictive value 99% above 200 HU; example patients at 20, 93 and 148 HU. Spongy bone in young adults and at other sites can be denser; the IAEA table gives only "compact bone", starting at +300. The "+300 HU or more" upper end is my inference from those two facts, not a quoted number. Recommend the site avoid a single narrow range for spongy bone.');
C('hounsfield-cortical-bone', 'Claim 5: Hounsfield units, compact (cortical) bone',
 'Dense compact bone measures from several hundred HU to +2000 HU or more, typically around +1000 to +1500 HU.',
 '+1000', 'HU', '+300 to +2500 (IAEA). Depends strongly on tube voltage: computed for reference cortical bone, +' + Math.round(b.hu80) + ' at 80 keV, +' + Math.round(b.hu70) + ' at 70 keV and +' + Math.round(b.hu60) + ' at 60 keV.',
 [IAEA, HEADPH, NIST+'bone.html'],
 'Draft (+500 up to about +1900 or more) is consistent with the sources; range replaced with the IAEA handbook Table 11.1 entry: Compact bone +1000 (+300 to +2500). A 2021 phantom paper lists skull bone at about 1500 HU at 120 kV on a GE Revolution scanner. The IAEA handbook notes that HU of high-atomic-number materials such as bone change most with tube voltage.');
// ---- 6 ----
C('ct-gantry-rotation-time', 'Claim 6: gantry rotation speed',
 'Inside the ring, the X-ray tube and the detector opposite it spin around the patient about two to four times every second.',
 '0.25 to 0.5', 's per rotation',
 'Fastest current models: 0.23 s (GE Revolution Apex), 0.24 s (Canon Aquilion ONE INSIGHT Edition, optional), 0.25 s (Siemens SOMATOM Force). The CT inside a Siemens Biograph Vision PET/CT: 0.33 s, with 0.30 and 0.28 s optional. Slower settings of 0.5 to 1 s are also used.',
 [IAEA, FORCE, GEPR, FDA_GE, CANON, VISION],
 'Draft confirmed with detail added. 0.5 s = 2 turns per second; 0.33 s = 3; 0.25 s = 4; 0.23 s = ' + n.rps023 + '. IAEA handbook: multi-detector scanners brought rotation time to 0.3-0.4 s, and "Forces of several tens of g arise for rotation times of the order of 0.25 s". Manufacturer pages read 2026-11-18; the GE press release calls 0.23 s "the world\'s fastest gantry speed", a marketing claim the site should not repeat as fact. The FDA 510(k) summary K213715 confirms the 0.23 s/rotation option. The fastest speeds are options used mainly for heart scans; a PET/CT body scan does not need them. "Slower settings of 0.5 to 1 s" is from the Townsend 2004 table (0.4 to 2.0 s on the PET/CT scanners of that year) and general practice, not from a current specification sheet.');
C('ct-detector-rows', 'Claim 6: number of detector rows',
 'Instead of one row of detector elements, a modern CT scanner has many rows side by side, commonly 64 and up to 320, so each turn records a band of the body rather than a single thin slice.',
 '64', 'detector rows (common); up to 320',
 '4 to 64 rows in the multi-detector scanners introduced from 1998; up to 320 rows of 0.5 mm, covering 16 cm per turn, on wide-detector scanners. The CT inside a Siemens Biograph Vision PET/CT is sold as 64- or 128-slice.',
 [IAEA, CANON, VISION, TOWNSEND04],
 'Draft ("64 to 320 detector rows") reworded: 64 to 320 is the range for current high-end stand-alone CT, but "slices" in product names is not always the number of physical rows, and PET/CT scanners have been built with 1, 2, 4, 8, 16, 64 and 128-slice CT (Townsend 2004 Table 2 lists 1 to 16 slices for the PET/CT designs of that year). IAEA handbook Table 11.2 and section 11.3.5: MDCT from 1998 with 4-64 active rows; volumetric CT from 2007 "with up to 320 active channels"; "With the 320 detector row CT scanner, one single rotation allows for coverage of 160 mm". Canon page: "320 rows, 0.5 mm", "16 cm z-axis". Each row has roughly 800 to 1000 detector elements along the arc (IAEA). "Commonly 64" is my reading of the IAEA text and the product pages, not a market statistic.');
C('ct-slice-thickness', 'Claim 6: thinnest slices',
 'The thinnest slices on most current scanners are about 0.5 to 0.625 mm, and the newest photon-counting scanners reach 0.2 mm.',
 '0.5 to 0.625', 'mm',
 '0.5 mm (Canon), 0.6 mm (Siemens), 0.625 mm (GE); 0.2 mm on the Siemens NAEOTOM Alpha photon-counting scanner. Whole-body PET/CT images are usually reconstructed much thicker.',
 [CANON, VISION, HEADPH, NAEOTOM, IAEA, TOWNSEND04],
 'Draft confirmed; 0.2 mm figure added. Canon Aquilion ONE INSIGHT page: 320 rows, 0.5 mm. Siemens Biograph Vision page: example protocols with 128 x 0.6 mm and 32 x 1.2 mm collimation. A GE Revolution scan with 0.625 mm slice thickness is described in PMC8693332. Siemens NAEOTOM Alpha page: "slice thickness of 0.2 mm", z-coverage 144 x 0.4 mm or 120 x 0.2 mm. IAEA: slice thickness "well below 1 mm" for MDCT. The example PET/CT scan in Townsend 2004 used 5 mm CT slices.');
C('ct-whole-body-scan-time', 'Claim 6: time for a whole-body CT pass',
 'The CT part of a PET/CT exam, which usually covers the body from the head or neck to the thighs, takes well under a minute.',
 '13', 's to cover 100 cm on a 16-slice PET/CT (2004 figure)',
 '13 s (16-slice) to 90 s (single-slice) per 100 cm on the PET/CT scanners of 2004; faster on current scanners. The PET part takes far longer, typically many minutes.',
 [TOWNSEND04, IAEA, FORCE],
 'Draft confirmed. Townsend et al. 2004 (J Nucl Med 45 suppl 1:4S-14S): "The time to scan an axial range of 100 cm varies from 13 s for a 16-slice system up to 90 s for a single-slice unit." IAEA handbook: MDCT makes it "possible to scan almost the entire body of an adult within one breath hold". Worked example (my arithmetic, not from a source): a 64 x 0.6 mm detector (38.4 mm) at pitch 1 and 0.5 s per turn moves ' + n.wholeBody_speed_mm_s + ' mm/s and covers 100 cm in ' + n.wholeBody_s + ' s. Siemens quotes up to 737 mm/s for its fastest stand-alone scanner. The scan range "head or neck to the thighs" is the usual oncology range and should be checked against the PET/CT protocol batch; the same paper gives PET times of 1 to 5 min per bed position.');
// ---- 7 ----
C('why-bone-stops-more-x-rays', 'Claim 7: why bone stops more X-rays',
 'Bone stops more X-rays than soft tissue for two reasons: it is nearly twice as dense, and about a third of its weight is calcium and phosphorus, heavier atoms that absorb X-ray photons outright far more readily than the hydrogen, carbon and oxygen of soft tissue.',
 'cortical bone: density 1.92 g/cm3; calcium 22.5% and phosphorus 10.3% by weight', '',
 'At 70 keV about ' + n.peB + ' percent of photon interactions in cortical bone are photoelectric absorption, compared with about ' + n.peW + ' percent in water; per centimeter, photoelectric absorption is about ' + Math.round(n.pePerCmRatio) + ' times more likely in bone than in water.',
 [TAB2, NIST+'bone.html', XCOM_MIX, XCOM_COMP, IAEA],
 'Draft confirmed and quantified. NIST Table 2 composition of cortical bone (ICRU-44): Ca 0.225, P 0.103, O 0.435, C 0.155, N 0.042, H 0.034 by weight; density 1.92 g/cm3. NIST XCOM at 70 keV: bone photoelectric 0.07729, incoherent (Compton) 0.1582, coherent (Rayleigh) 0.02157 cm2/g; water photoelectric 0.008969, incoherent 0.1734, coherent 0.01048 cm2/g. Shares: bone ' + n.peB + '% photoelectric / ' + n.incB + '% Compton / ' + n.cohB + '% Rayleigh; water ' + n.peW + '% / ' + n.incW + '% / ' + n.cohW + '%. Photoelectric absorption per gram is ' + n.pePerGramRatio + ' times higher in bone, per cm ' + n.pePerCmRatio + ' times. NOTE: even in bone at 70 keV, Compton scattering is still the most common single interaction (' + n.incB + '%); photoelectric absorption becomes the larger share only at about 50 keV and below. So say photoelectric absorption is "far more likely in bone than in soft tissue", not that it is the main interaction in bone at 70 keV. IAEA handbook: the photoelectric cross-section rises steeply with atomic number and falls steeply with energy; "the scatter interactions are predominant for soft tissue, but the photoelectric interaction is predominant for bone over much of the diagnostic energy range".');
C('soft-tissue-mostly-scatters', 'Claim 7: soft tissue behaves like water and mostly scatters',
 'Soft tissues are mostly water, differ from water by only a few percent in how strongly they attenuate X-rays, and at CT energies about nine out of ten of their interactions with X-ray photons are Compton scattering.',
 n.incW, 'percent of interactions in water at 70 keV that are Compton scattering',
 'Water at 70 keV: about ' + n.incW + '% Compton scatter, ' + n.cohW + '% Rayleigh scatter, ' + n.peW + '% photoelectric absorption. Muscle and soft tissue are about ' + n.musclePctAbove + ' to ' + n.softPctAbove + '% above water in mu; fat is about ' + n.fatPctBelow + '% below.',
 [XCOM_COMP, XCOM_MIX, NIST+'tissue.html', NIST+'muscle.html', NIST+'adipose.html', IAEA],
 'Draft confirmed and quantified from NIST XCOM (see tables.interactions). mu at 70 keV: water ' + sig(w.mu70) + ', muscle ' + sig(mu_.mu70) + ', soft tissue ' + sig(s.mu70) + ', fat ' + sig(f.mu70) + ' per cm. This small spread (a few percent, that is a few tens of HU) is the reason CT needs precise measurements to tell soft tissues apart. At 511 keV more than 99 percent of interactions in water, soft tissue and bone are Compton scattering.');
// ---- 8 ----
C('three-fates-of-an-x-ray-photon', 'Claim 8: what can happen to one X-ray photon in the body',
 'Each X-ray photon entering the body does one of three things: it passes straight through and reaches the detector, it is absorbed by an atom and disappears (the photoelectric effect), or it bounces off an electron in a new direction (scattering).',
 'three outcomes: transmitted, absorbed, scattered', '',
 'Two kinds of scattering occur at CT energies: Compton scattering (the photon gives part of its energy to an electron; about ' + n.incW + '% of interactions in water at 70 keV) and Rayleigh scattering (the photon changes direction and keeps its energy; about ' + n.cohW + '%). A scattered photon can go on to scatter again, be absorbed, or leave the body.',
 [IAEA, XCOM_COMP],
 'Draft confirmed; Rayleigh (coherent) scattering added as a minor second kind of scatter so the site does not imply Compton is the only one. IAEA handbook chapter 2: photoelectric effect ("The incident photon disappears in the photoelectric interaction"), coherent (Rayleigh) scattering, Compton scattering; a scattered photon may "be followed by a third scatter, photoelectric absorption or no further interactions". Pair production needs at least 1022 keV, so it plays no part in CT or PET. The image is formed from the photons that pass straight through; scattered photons that still reach the detector add haze, which the anti-scatter grid on the detector reduces. "Bounces off an electron" is a simplification that fits Compton scattering; Rayleigh scattering involves the atom as a whole.');
C('photons-do-not-slow-down', 'Claim 8: attenuation means fewer photons, not slower ones',
 'X-ray photons do not slow down in the body; they all travel at the speed of light, and tissue only reduces how many of them arrive, which is what attenuation means.',
 'speed unchanged; number reduced', '',
 'A Compton-scattered photon does lose energy, but it still travels at the speed of light: a 70 keV photon scattered through 90 degrees leaves with about ' + compton(70).after90deg_keV + ' keV, and a 511 keV photon with about ' + compton(511).after90deg_keV + ' keV.',
 [IAEA],
 'Draft confirmed. The Beer-Lambert law (IAEA Eq. 11.1) is a statement about the number (intensity) of unscattered photons. Lower photon energy means longer wavelength, not lower speed. The speed statement is standard physics rather than a sentence quoted from the handbook; for X-rays the refractive index of tissue differs from 1 by a few parts per million or less, so "at the speed of light" is accurate for the site. Compton energies computed from E_after = E / (1 + (E / 511 keV) x (1 - cos angle)): 70 keV gives ' + compton(70).after90deg_keV + ' keV at 90 degrees and ' + compton(70).after180deg_keV + ' keV at 180 degrees; 511 keV gives ' + compton(511).after90deg_keV + ' keV and ' + compton(511).after180deg_keV + ' keV. GAME NOTE: if the site game shows photons slowing down in dense tissue, it should say plainly that this is a visual stand-in for "fewer photons get through", and that real photons never slow.');
// ---- 9 ----
C('radon-transform', 'Claim 9: image reconstruction, the Radon transform',
 'The mathematics behind CT goes back to 1917, when the mathematician Johann Radon showed that a two-dimensional pattern can be recovered from the sums measured along all the straight lines crossing it; the set of those line sums is now called the Radon transform.',
 '1917', 'year',
 'Radon\'s paper was not known to the people who built CT: Allan Cormack solved the problem independently, published in 1963 and 1964, and wrote that he learned of Radon\'s work only in the early 1970s.',
 [CORMACK, NOBELPRESS, IAEA],
 'Draft confirmed. Cormack Nobel lecture (1979): "Only then [the early seventies] did I learn of Radon\'s work on the line integral problem", reference 3: Radon, J., Ber. Sachs. Akad. Wiss. 69, 262 (1917); "Radon provided an affirmative answer and a formula". Nobel press release 1979: Cormack "published his analysis of the problem in two scientific publications in 1963 and 1964" and "was not aware then that the key mathematical problems had been considered earlier". IAEA handbook section 11.4.2 uses "Radon space" and "2-D Radon transform" for CT projection data. Radon\'s first name and nationality (Johann, Austrian) are from general knowledge; the lecture gives only "Radon, J. H.", so the name should be checked by the history batch and the nationality is left out. The range text says "not known to the people who built CT", which is supported for Cormack; Hounsfield\'s lecture does not mention Radon.');
C('filtered-back-projection', 'Claim 9: image reconstruction, filtered back-projection',
 'For about four decades the standard way to turn the measurements into a picture was filtered back-projection: each measured profile is sharpened with a "ramp" filter and then smeared back across the image along the direction it was measured from, and the smears from all angles add up to the cross-section.',
 'about 40', 'years as the standard method',
 'Without the filter step, simple back-projection gives a strongly blurred image. The ramp filter is also called the Ram-Lak (Ramachandran-Lakshminarayanan) filter; scanners offer modified versions tuned for soft tissue or bone.',
 [IAEA, KOETZIER, WILLEMINK],
 'Draft confirmed. Koetzier et al. 2023 (Radiology 306:e221257): "Filtered back projection (FBP) has been the standard CT image reconstruction method for 4 decades." Willemink and Noel 2019 (Eur Radiol 29:2185-95): "FBP was the method of choice for decades". IAEA handbook section 11.4: simple back-projection "yields a strongly blurred image"; the filter is "a ramp filter in the frequency domain ... Ramachandran-Lakshminarayanan filter, also called the Ram-Lak or ramp filter". "Sharpened" is plain-language for a filter that boosts fine detail (high spatial frequencies).');
C('first-ct-used-iterative-reconstruction', 'Claim 9: image reconstruction, history',
 'The first CT scanners of the early 1970s built their images with a step-by-step (iterative) method, but the computers of the time were too slow for it and filtered back-projection soon replaced it.',
 'early 1970s', '',
 'The first clinical scan took about 5 minutes to acquire and about as long to reconstruct, at 80 x 80 pixels; most CT images today are 512 x 512 pixels.',
 [WILLEMINK],
 'ADDED nuance: the draft says FBP "was the standard method for decades", which is true, but it was not the original method. Willemink and Noel 2019: "The first CT scanners in the early 1970s already used iterative reconstruction algorithms"; "Originally, CT images were reconstructed with an iterative method called algebraic reconstruction technique (ART). Due to lack of computational power, this technique was quickly replaced by simple analytic methods such as filtered back projection"; "The first clinical CT scan took about 5 min, and image reconstruction took approximately the same time ... only 80 x 80 pixels"; "512 x 512 pixels for most" current applications. Scan and reconstruction times for the first scanner differ between accounts; the history batch should own those numbers.');
C('iterative-reconstruction-return', 'Claim 9: image reconstruction, iterative methods',
 'Since about 2009, faster computers have let scanner makers bring back iterative reconstruction, which repeatedly adjusts the image until it agrees with the measurements and gives cleaner pictures at lower radiation dose; it is now common.',
 '2009', 'year (approximate start of routine clinical use)',
 'Within a few years of 2009 all major CT makers offered iterative reconstruction. Types range from "hybrid" methods that mainly reduce noise to full model-based methods.',
 [WILLEMINK, IAEA, KOETZIER],
 'Draft confirmed. Willemink and Noel 2019: "it took until 2009 for the first iterative reconstruction algorithms to come commercially available"; "In 2009, the first IR algorithm called IRIS (iterative reconstruction in image space, Siemens Healthineers) received FDA clearance"; "Within a few years, all major CT vendors introduced IR algorithms". DOUBT on the "first": other accounts date GE\'s ASiR to 2008, which I did not verify; the statement therefore says "since about 2009" and names no first product. IAEA handbook (2014): "Iterative (statistical) reconstructions are now commonly used in CT."');
C('deep-learning-reconstruction', 'Claim 9: image reconstruction, deep learning',
 'The newest method, deep-learning reconstruction, uses a neural network trained on pairs of lower-quality and higher-quality scans to produce low-noise images; the first such products for CT were cleared by the U.S. Food and Drug Administration in 2019.',
 '2019', 'year of first FDA clearances',
 'By early 2023, three CT makers (GE, Canon, Philips) and two independent software companies had FDA-cleared deep-learning products.',
 [KOETZIER],
 'Draft confirmed and dated. Koetzier et al. 2023: "In 2019, TrueFidelity (GE Healthcare) became the first DLR technique approved by the FDA"; "The second DLR algorithm approved by the FDA was ... AiCE, Canon Medical Systems ... in 2019"; Philips Precise Image in 2022; two image-denoising products (ClariCT.AI, PixelShine) cleared in 2019. The statement says "the first such products ... in 2019", which is true whichever product is counted first. The review writes "approved"; the regulatory term for these devices is "cleared". The review abstract, as returned by search, also reports dose reductions of up to 71 percent in selected studies; I did not check that figure in the full text, so it is left out of the statement.');
// ---- 10 ----
C('ct-based-attenuation-correction', 'Claim 10: CT-based attenuation correction in PET/CT',
 'In a PET/CT scanner the CT image does a second job: it is converted into a map of how strongly each part of the body attenuates 511 keV photons, and that map is used to correct the PET data for the photon pairs that were absorbed or scattered inside the patient.',
 'attenuation correction', '',
 'Before PET/CT, the map came from a separate, lengthy transmission scan with radioactive sources; replacing it with CT cut whole-body scan time by up to 40 percent and gave a nearly noise-free map.',
 [TOWNSEND04, KINAHAN03, SURESHBABU, BOELLAARD],
 'Draft confirmed. Townsend et al. 2004: "the use of CT images for attenuation correction of the PET emission data, eliminating the need for a separate, lengthy PET transmission scan ... not only reduces whole-body scan times by up to 40% but also provides essentially noiseless ACFs". Kinahan et al. 2003 (Semin Nucl Med 33:166-79) abstract: transmission methods use "positron sources, gamma-ray sources, or x-ray sources"; error sources for the CT method are breathing mismatch between CT and PET, contrast agents, metal implants, and arms in the field of view. The EANM FDG PET/CT guideline (Boellaard 2015) recommends looking at images with and without attenuation correction to spot CT-caused artifacts.');
C('ct-to-511-kev-conversion', 'Claim 10: converting CT numbers to 511 keV attenuation',
 'Because CT measures attenuation at about 70 keV and PET needs it at 511 keV, the scanner rescales every pixel, using one straight-line conversion for air, lung and soft tissue and a second, less steep line for bone.',
 'mu(511 keV) = 9.6e-5 x (HU + 1000) per cm below about 50 HU', 'per cm',
 'This two-line ("bilinear") conversion gives 0.096 per cm for water (0 HU) and 0 for air (-1000 HU). Above the break point the slope is smaller and depends on the CT tube voltage. The ratio mu(511 keV)/mu(70 keV) is about ' + sig(n.scaleWater,2) + ' for water and about ' + sig(n.scaleBone,2) + ' for dense bone.',
 [CARNEY06, BURGER02, TOWNSEND04, SURESHBABU, NIST+'water.html', NIST+'bone.html'],
 'Draft confirmed with one correction of attribution (see kinahan-1998-reference): the bilinear method is described by Burger et al. 2002 for the GE Discovery LS ("uses a bilinear function based on the attenuation of water and cortical bone at the CT and PET energies") and by Carney et al. 2006 ("9.6 x 10(-5) (HU + 1000) below a threshold of approximately 50 HU and a(HU + 1000) + b above the threshold, where a and b are fixed parameters that depend on the kVp setting"). Break points and slopes differ between manufacturers. Check: Carney\'s line gives ' + n.carneyLung + ' per cm for the inflated-lung row (HU ' + Math.round(l.hu70) + '), against ' + sig(l.mu511,3) + ' computed from NIST. Scale ratios computed from NIST XCOM: water 0.09598/0.1929 = ' + n.scaleWater + '; cortical bone 0.08938/0.2570 = ' + n.scaleBone + '. Contrast agents and metal upset the conversion because they are bright on CT for a reason (high atomic number) that matters little at 511 keV.');
C('kinahan-1998-reference', 'Claim 10: key reference, Kinahan et al. 1998',
 'A 1998 paper in the journal Medical Physics by Paul Kinahan, David Townsend, Thomas Beyer and Donald Sashin showed, using CT and PET scans of test objects and of people, that a CT image can be used to correct PET data for attenuation in a combined PET/CT scanner.',
 'Kinahan PE, Townsend DW, Beyer T, Sashin D. Attenuation correction for a combined 3D PET/CT scanner. Med Phys. 1998;25(10):2046-2053. doi:10.1118/1.598392', '',
 'Published October 1998; PubMed ID 9800714. The data came from separate CT and PET scanners, with the images aligned by software.',
 [KINAHAN98, TOWNSEND04],
 'Reference CONFIRMED (authors, journal, year, volume 25, issue 10, pages 2046-53, DOI). CORRECTION to the draft: this paper did not propose "bilinear scaling". Its abstract compares three methods, "segmentation, scaling, and our proposed hybrid segmentation/scaling method", for converting "from an effective CT photon energy of 70 keV to the PET photon energy of 511 keV"; in the hybrid method a threshold separates bone from non-bone and each gets its own scale factor (Townsend 2004). The bilinear function used on later scanners is a close relative (Burger 2002, Carney 2006). First-author affiliation in PubMed: Department of Radiology, University of Pittsburgh. The abstract calls the work a "proof of principle" and concludes "using CT information is a feasible way to obtain attenuation correction factors for 3D PET". The statement avoids the word "first": X-ray-based attenuation correction had been explored earlier for SPECT/CT, and I did not check priority.');
C('pet-without-attenuation-correction', 'Claim 10: what an uncorrected PET image looks like',
 'Without attenuation correction a PET image is misleading in a recognizable way: the skin and the lungs look too bright, and the deep center of the body looks too dim.',
 'skin and lungs falsely bright; deep tissue falsely dim', '',
 'The error grows with body size. Doctors still look at the uncorrected images as a cross-check, because problems in the CT (metal, contrast agent, breathing mismatch) can create false bright spots in the corrected ones.',
 [BAI03, SURESHBABU, BOELLAARD],
 'Draft confirmed. Bai, Kinahan et al. 2003 (J Nucl Med 44:1855-61): an image reconstructed without attenuation correction "illustrates the well-known artifacts of elevated tracer concentration in the lungs and skin"; in uniform regions such as the abdomen only "central regions of lower, or even negative, tracer concentration" are consistent with the uncorrected data; "The well-known disadvantages of not performing attenuation correction are the inaccuracies in the uptake, shape, and location of lesions". Reason: photon pairs from deep in the body must cross more tissue, so fewer are detected; pairs from the skin, and pairs crossing the low-density lungs, are lost less. Sureshbabu and Mawlawi 2005 (J Nucl Med Technol 33:156-61) and the EANM guideline (Boellaard 2015) describe using non-corrected images to check for CT-caused artifacts. "The error grows with body size" follows from the exponential law (see photon-pair-loss-in-the-body) and is not a quoted sentence.');
C('photon-pair-loss-in-the-body', 'Claim 10: size of the attenuation effect at 511 keV',
 'A PET event is counted only if both 511 keV photons escape the body, and along a line through 30 cm of tissue only about 1 pair in ' + Math.round(n.pair30factor) + ' does, so the correction is large.',
 n.pair30, 'percent of photon pairs surviving a 30 cm path in water',
 'Survival for a total path in water of 10 / 20 / 30 / 40 cm: ' + pairSurvival.map(p => p.pctOfPhotonPairsDetectable).join(' / ') + ' percent (correction factors ' + pairSurvival.map(p => p.correctionFactor).join(' / ') + '). The loss depends on the total tissue thickness along the line, not on where along the line the pair started.',
 [NIST+'water.html', BURGER02, BAI03],
 'Computed here, not quoted: pair survival = exp(-mu x D) with mu(water, 511 keV) = ' + sig(w.mu511) + ' per cm and D the total path length through the body along the line joining the two detectors (each photon survives with probability exp(-mu x its own path), and the two paths add up to D). 30 cm: exp(-' + sig(w.mu511) + ' x 30) = ' + sig(Math.exp(-w.mu511*30),3) + ', that is 1 in ' + n.pair30factor + '. Real bodies are not pure water (lungs attenuate less, bone more), and 30 cm is an illustrative adult torso width. This is added background for the site text; the draft did not include a number.');

const out = {
  batch: 'ct-physics',
  verifiedOn: '2026-11-18',
  claims,
  tables: {
    attenuation,
    transmission,
    hounsfield,
    interactions,
    pairSurvival511keV: pairSurvival,
    tableNotes: {
      attenuation: 'massAtt_* columns are cm2/g exactly as printed in the NIST X-ray mass attenuation coefficient tables. mu_70keV_per_cm and mu_511keV_per_cm = density x log-log interpolation between 60 and 80 keV and between 500 and 600 keV. xcom_* columns are from the NIST XCOM database run at exactly 70 and 511 keV with the NIST Table 2 compositions; XCOM reproduces the tabulated 60, 80 and 500 keV values exactly and is 0.2 to 1.8% lower than the interpolated values at 70 keV. Densities are from NIST Table 2 except inflated lung (assumed 0.26 g/cm3). typicalHU are literature ranges (see tables.hounsfield).',
      transmission: 'Percent of 70 keV photons that cross the stated thickness without being absorbed or scattered = 100 x exp(-mu x thickness), using mu_70keV_per_cm from tables.attenuation. xcomCheck_pctThrough repeats the calculation with the XCOM mu. at511keV_pctThrough is the same for a single 511 keV photon.',
      interactions: 'Share of each interaction type, from NIST XCOM partial coefficients (photoelectric, incoherent = Compton, coherent = Rayleigh).',
      hounsfield: 'typicalHU = [low, high] range recommended for the site, with the evidence in "basis".',
      pairSurvival511keV: 'Percent of annihilation photon pairs for which both photons escape a water path of the given total length; correctionFactor is the number the measured counts must be multiplied by.',
    },
  },
};
fs.writeFileSync(process.argv[2], JSON.stringify(out, null, 2), 'utf8');
console.log('claims', claims.length);
console.log(JSON.stringify(n));
console.table(attenuation.map(r => ({ m: r.material.slice(0,18), rho: r.density_g_cm3, mu70: r.mu_70keV_per_cm, mu511: r.mu_511keV_per_cm, x70: r.xcom_mu_70keV_per_cm, x511: r.xcom_mu_511keV_per_cm, HU70: r.computedHU_monoenergetic.at70keV })));
console.table(transmission.map(r => ({ m: r.material.slice(0,18), c1: r.pctThrough_1cm, c5: r.pctThrough_5cm, c10: r.pctThrough_10cm, c20: r.pctThrough_20cm })));
console.table(interactions.map(r => ({ m: r.material.slice(0,18), ...r.at70keV_pct, pe511: r.at511keV_pct.photoelectricAbsorption, inc511: r.at511keV_pct.comptonScatter })));
for (const c of claims) console.log('-', c.id, '|', c.statement);

