// Builds draft.json for batch "ct-physics". All derived numbers are computed here.
// Usage: node build_draft.js <output path>
const fs = require('fs');
const NIST = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/ComTab/';
const TAB2 = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/tab2.html';
const TAB4 = 'https://physics.nist.gov/PhysRefData/XrayMassCoef/tab4.html';
const XCOM_COMP = 'https://physics.nist.gov/cgi-bin/Xcom/xcom2?Method=Comp&Output2=Hand';
const XCOM_MIX = 'https://physics.nist.gov/cgi-bin/Xcom/xcom2?Method=Mix&Output2=Hand';
const IAEA = 'https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1564webNew-74666420.pdf';
const eutils = id => 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=pubmed&id=' + id + '&rettype=abstract&retmode=text';
const KINAHAN98 = eutils(9800714), KINAHAN03 = eutils(12931319), CARNEY06 = eutils(16696474), BURGER02 = eutils(12111133);
const TOWNSEND04 = 'https://jnm.snmjournals.org/content/45/1_suppl/4S.full.pdf';
const BAI03 = 'https://jnm.snmjournals.org/content/jnumed/44/11/1855.full.pdf';
const WILLEMINK = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6443602/';
const KOETZIER = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9968777/';
const CORMACK = 'https://www.nobelprize.org/uploads/2018/06/cormack-lecture.pdf';
const HOUNSFIELD = 'https://www.nobelprize.org/uploads/2018/06/hounsfield-lecture.pdf';
const NOBELPRESS = 'https://www.nobelprize.org/prizes/medicine/1979/press-release/';
const SURESHBABU = 'https://tech.snmjournals.org/content/33/3/156';
const BOELLAARD = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4315529/';
const VISION = 'https://www.siemens-healthineers.com/en-us/molecular-imaging/pet-ct/biograph-vision';
const FORCE = 'https://www.siemens-healthineers.com/en-us/computed-tomography/dual-source-ct/somatom-force';
const NAEOTOM = 'https://www.siemens-healthineers.com/en-us/computed-tomography/photon-counting-ct-scanner/naeotom-alpha';
const CANON = 'https://us.medical.canon/products/computed-tomography/aquilion-one-insight/';
const GEPR = 'https://www.gehealthcare.com/en-us/about/newsroom/press-releases/ge-healthcare-introduces-modular-scalable-ct-platform-to-minimize-technology-obsolescence';
const FDA_GE = 'https://www.accessdata.fda.gov/cdrh_docs/pdf21/K213715.pdf';
const LAMBA = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5015439/';
const PICKHARDT = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC3736840/';
const AORTA1 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9816921/';
const AORTA2 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12426566/';
const EFFE1 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5966206/';
const EFFE2 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7851788/';
const HEADPH = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8693332/';
const HU1980 = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6160654/';

// ---- data read from NIST (cm2/g) ----
// m60, m80, m500, m600: X-ray mass attenuation coefficient tables (tab4 pages), exactly as printed.
// x70, x511: NIST XCOM run directly at 0.07 and 0.511 MeV ("total attenuation with coherent scattering").
// coh/inc/pe: XCOM partial coefficients at 0.07 MeV; coh511/inc511/pe511 at 0.511 MeV.
const M = [
 { key:'air', material:'Air (dry, near sea level)', rho:1.205e-3, m60:0.1875, m80:0.1662, m500:0.08712, m600:0.08055, x70:0.1750, x511:0.08632, coh:0.01031, inc:0.1555, pe:0.009157, coh511:2.110e-4, inc511:0.08609, pe511:1.886e-5, page:'air.html', hu:[-1000,-1000] },
 { key:'lung', material:'Inflated lung (NIST lung-tissue mu/rho applied at an assumed density of 0.26 g/cm3)', rho:0.26, m60:0.2053, m80:0.1826, m500:0.09607, m600:0.08882, x70:0.1920, x511:0.09519, coh:0.01032, inc:0.1720, pe:0.009643, coh511:2.121e-4, inc511:0.09496, pe511:1.963e-5, page:'lung.html', hu:[-950,-600] },
 { key:'adipose', material:'Adipose tissue (fat)', rho:0.95, m60:0.1974, m80:0.1800, m500:0.09696, m600:0.08965, x70:0.1875, x511:0.09607, coh:0.007882, inc:0.1744, pe:0.005185, coh511:1.597e-4, inc511:0.09590, pe511:1.022e-5, page:'adipose.html', hu:[-130,-70] },
 { key:'water', material:'Water (liquid)', rho:1.0, m60:0.2059, m80:0.1837, m500:0.09687, m600:0.08956, x70:0.1929, x511:0.09598, coh:0.01048, inc:0.1734, pe:0.008969, coh511:2.151e-4, inc511:0.09575, pe511:1.778e-5, page:'water.html', hu:[0,0] },
 { key:'soft', material:'Soft tissue (ICRU-44)', rho:1.06, m60:0.2048, m80:0.1823, m500:0.09598, m600:0.08873, x70:0.1916, x511:0.09510, coh:0.01019, inc:0.1719, pe:0.009547, coh511:2.093e-4, inc511:0.09487, pe511:1.950e-5, page:'tissue.html', hu:[20,70] },
