const loglog = (E,E1,y1,E2,y2) => Math.exp(Math.log(y1) + (Math.log(y2)-Math.log(y1))*(Math.log(E)-Math.log(E1))/(Math.log(E2)-Math.log(E1)));
const sig = (x,n=4) => Number(x.toPrecision(n));
const T = (mu,x) => 100*Math.exp(-mu*x);
for (const m of M) {
  m.mr70 = loglog(70,60,m.m60,80,m.m80); m.mr511 = loglog(511,500,m.m500,600,m.m600);
