  m.mu70x = m.x70*m.rho; m.mu511x = m.x511*m.rho;
  m.mu60 = m.m60*m.rho; m.mu80 = m.m80*m.rho;
}
const by = k => M.find(m => m.key===k);
const w = by('water'), a = by('air'), b = by('bone'), l = by('lung'), f = by('adipose'), s = by('soft'), mu_ = by('muscle');
const HU2 = (mu,muw,mua) => 1000*(mu-muw)/(muw-mua);   // two-point form
const HU1 = (mu,muw) => 1000*(mu-muw)/muw;             // IAEA form
for (const m of M) {
